inputs = ['ggd', 'uujd', 'fuj', 'cixd', 'jbua']
outputs = ['ffbhw', 'ffjbhw', 'ffj', 'cicibhwbhw', 'jbfa']

print("Input -> Output transformations:")
for i in range(len(inputs)):
    print(f"'{inputs[i]}' -> '{outputs[i]}'")

# Let's manually examine what's changing
print("\nDetailed analysis:")
for i in range(len(inputs)):
    in_str = inputs[i]
    out_str = outputs[i]
    print(f"Input: '{in_str}' -> Output: '{out_str}'")

    # Find differences
    min_len = min(len(in_str), len(out_str))
    diff_pos = -1
    for j in range(min_len):
        if in_str[j] != out_str[j]:
            diff_pos = j
            break

    if diff_pos == -1:
        if len(in_str) != len(out_str):
            diff_pos = min_len
        else:
            print("  No differences found")
            continue

    print(f"  First difference at position {diff_pos}")
    if diff_pos < len(in_str) and diff_pos < len(out_str):
        print(f"  Changed from '{in_str[diff_pos]}' to '{out_str[diff_pos]}'")
    elif diff_pos < len(in_str):
        print(f"  Removed character '{in_str[diff_pos]}'")
    elif diff_pos < len(out_str):
        print(f"  Added character '{out_str[diff_pos]}'")

